  for (const m of readFileSync(new URL('../src/ui.html', import.meta.url), 'utf8').matchAll(/^  (?:async )?function (\w+)\(/gm)) seen.set(m[1], (seen.get(m[1]) || 0) + 1);
  const dup = [...seen].filter(([, n]) => n > 1).map(([k]) => k);
